    params.set("event_type", filters.event_type);
  if (filters.status)
    params.set("status", filters.status);
  if (filters.tag)
    params.set("tag", filters.tag);
  if (filters.since)
    params.set("since", filters.since);
  if (filters.until)
    params.set("until", filters.until);
